import java.util.*;

class Solution {
    public int oddOneOut(int[] nums) {
        int result = 0;
        for (int b = 0; b < 32; b++) {
            int count = 0;
            for (int v : nums) count += (v >> b) & 1; // how many numbers have bit b
            if (count % 3 != 0) result |= 1 << b;     // left-over bit belongs to the single value
        }
        return result; // bit 31 set => negative, handled by two's complement
    }
}

